// Fill a full symmetric 6x6 Gram matrix for (l, m). Returns false if (l, m) is out of range.
inline bool c_angular_gram(int degree_l, int order_m, double gram[6][6]) {
    if (degree_l < C_ANGULAR_GRAM_MIN_L || degree_l > C_ANGULAR_GRAM_MAX_L
        || order_m < 0 || order_m > degree_l) {
        return false;
    }
    const double* upper = C_ANGULAR_GRAM_TABLE[c_angular_gram_row(degree_l, order_m)];
    int idx = 0;
    for (int i = 0; i < 6; ++i) {
        for (int j = i; j < 6; ++j) {
            gram[i][j] = gram[j][i] = upper[idx++];
        }
    }
    return true;
}

